'use strict';
const categories=[['nails','Маникюр','nails'],['hair','Окрашивание','hair'],['cut','Стрижка','hair2'],['brows','Брови','brows'],['makeup','Макияж','makeup'],['lashes','Ресницы','lashes']];
const masters=[{id:1,name:'Анна Миронова',role:'Колорист · парикмахер',cat:'hair',service:'Сложное окрашивание',price:5500,time:240,rating:'4,9',reviews:38,area:'Центр',address:'ул. Ленина, 245',image:'hair',avatar:'portrait1',title:'Мягкий блонд и естественные оттенки',experience:'7 лет',text:'Помогаю найти оттенок, с которым комфортно каждый день. Перед окрашиванием обсуждаем пожелания, состояние волос и уход.',work:'Мягкий переход цвета, объёмная укладка. Точную технику и стоимость мастер обсуждает на консультации.'},{id:2,name:'Мария Соколова',role:'Мастер маникюра',cat:'nails',service:'Маникюр с покрытием',price:1800,time:120,rating:'5,0',reviews:24,area:'Юго-Западный',address:'ул. Тухачевского, 19',image:'nails',avatar:'portrait2',title:'Аккуратный маникюр, который радует',experience:'5 лет',text:'Люблю чистые формы, спокойные оттенки и внимание к деталям. Помогу подобрать длину и дизайн под ваш образ жизни.',work:'Маникюр с выравниванием и однотонным покрытием. Форма и оттенок выбираются вместе с клиентом.'},{id:3,name:'Екатерина Белова',role:'Визажист',cat:'makeup',service:'Вечерний макияж',price:3000,time:90,rating:'4,9',reviews:31,area:'Центр',address:'ул. Мира, 280',image:'makeup',avatar:'portrait3',title:'Макияж с вниманием к вашей красоте',experience:'6 лет',text:'Создаю образы для важных событий и красивых обычных дней. Обсудим ваши привычки, пожелания и комфортную яркость.',work:'Выразительный макияж с акцентом на глаза и ровным тоном. Оттенки подбираются индивидуально.'},{id:4,name:'Полина Орлова',role:'Бровист',cat:'brows',service:'Оформление бровей',price:1200,time:60,rating:'4,8',reviews:19,area:'Северо-Западный',address:'ул. Доваторцев, 8',image:'brows',avatar:'portrait2',title:'Естественные брови и мягкий взгляд',experience:'4 года',text:'Сохраняю естественный характер бровей. Вместе подберём форму и интенсивность оттенка.',work:'Подбор формы, коррекция и окрашивание. В демонстрационном профиле использована иллюстративная фотография.'},{id:5,name:'Дарья Лебедева',role:'Парикмахер-стилист',cat:'cut',service:'Стрижка и укладка',price:2200,time:90,rating:'4,9',reviews:27,area:'Юго-Западный',address:'ул. 50 лет ВЛКСМ, 28',image:'hair2',avatar:'portrait1',title:'Форма, которую легко поддерживать',experience:'8 лет',text:'Подбираю стрижку под текстуру волос и вашу привычную укладку. Покажу, как повторить результат дома.',work:'Стрижка с учётом естественного движения волос и укладка. Фотография иллюстрирует направление работы.'},{id:6,name:'Алина Волкова',role:'Мастер по ресницам',cat:'lashes',service:'Наращивание ресниц',price:2500,time:150,rating:'4,9',reviews:22,area:'Центр',address:'ул. Дзержинского, 114',image:'lashes',avatar:'portrait3',title:'Выразительный взгляд каждый день',experience:'5 лет',text:'Подбираю эффект под форму глаз и желаемый результат. Обсуждаем длину, изгиб и рекомендации по уходу.',work:'Индивидуальный подбор эффекта. Фотография иллюстративная и не подтверждает результат конкретной процедуры.'}];
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=read('forma-saved',[]),bookings=read('forma-bookings',[]),state={view:'home',cat:'',price:0,area:'',sort:'recommended',search:''};
function persist(){try{localStorage.setItem('forma-saved',JSON.stringify(saved));localStorage.setItem('forma-bookings',JSON.stringify(bookings))}catch{toast('Хранилище браузера недоступно. Данные останутся до закрытия страницы.')}updateCount()}
function updateCount(){$('#savedCount').textContent=saved.length||''}updateCount();
function money(n){return n.toLocaleString('ru-RU')+' ₽'}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function favorite(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render(false)}
function card(m){return `<article class="card"><div class="cover"><a href="#master/${m.id}" aria-label="Работы мастера ${m.name}"><img src="assets/${m.image}.jpg" alt="${m.title}" loading="lazy"></a><span class="cover-label">${m.service}</span><button class="heart ${saved.includes(m.id)?'on':''}" aria-label="${saved.includes(m.id)?'Убрать из избранного':'Сохранить мастера'}: ${m.name}" aria-pressed="${saved.includes(m.id)}" data-save="${m.id}">${saved.includes(m.id)?'♥':'♡'}</button></div><div class="card-content"><div class="person"><img class="avatar" src="assets/${m.avatar}.jpg" alt=""><div><h3><a href="#master/${m.id}">${m.name}</a></h3><p>${m.role}</p></div></div><div class="rating"><span class="star">★</span><strong>${m.rating}</strong><span class="muted">· ${m.reviews} ${m.reviews===31?'отзыв':m.reviews===24?'отзыва':'отзывов'}</span></div><div class="location">⌖ ${m.area} · Ставрополь</div><div class="price"><span>${m.service}</span><strong>${money(m.price)}</strong></div><a class="primary" href="#master/${m.id}">Посмотреть работы и записаться <span></span></a></div></article>`}
function filtered(){let list=masters.filter(m=>(state.view!=='saved'||saved.includes(m.id))&&(!state.cat||m.cat===state.cat)&&(!Number(state.price)||m.price<=Number(state.price))&&(!state.area||m.area===state.area)&&(!state.search||(m.name+' '+m.role+' '+m.service).toLowerCase().includes(state.search.toLowerCase())));if(state.sort==='cheap')list.sort((a,b)=>a.price-b.price);if(state.sort==='rating')list.sort((a,b)=>parseFloat(b.rating.replace(',','.'))-parseFloat(a.rating.replace(',','.')));return list}
function results(){const list=filtered();$('#results').innerHTML=list.length?list.map(card).join(''):`<div class="empty" style="grid-column:1/-1"><h2>${state.view==='saved'&&!saved.length?'Сохраните тех, кто понравился':'Таких мастеров пока нет'}</h2><p>${state.view==='saved'&&!saved.length?'Нажмите на сердечко в карточке мастера.':'Попробуйте изменить услугу, цену или район.'}</p><button class="primary" data-reset>${state.view==='saved'&&!saved.length?'Найти мастера':'Сбросить фильтры'}</button></div>`;$('#resultCount').textContent=list.length+' '+(list.length===1?'мастер':'мастеров')+' · демонстрационные профили'}
function listing(){const home=state.view==='home';app.innerHTML=`${home?`<section class="hero"><div class="eyebrow">Ваш город. Ваш мастер. Ваш образ.</div><h1>Что хотите<br><em>сделать для себя?</em></h1><p>Выберите услугу. Посмотрите работы.<br>Найдите мастера, которому доверитесь.</p><div class="hero-note">Никакого сложного выбора.<br>Все работы, цены и отзывы —<br>в одном месте.</div></section><section class="categories" aria-label="Выберите услугу">${categories.map(([id,label,img])=>`<button class="category ${state.cat===id?'active':''}" data-cat="${id}" aria-pressed="${state.cat===id}"><img src="assets/${img}.jpg" alt=""><div>${label}<span>${state.cat===id?'✓':''}</span></div></button>`).join('')}</section>`:'<button class="back" data-view="home">&larr; Найти мастера</button>'}<section id="catalog"><div class="section-head"><div><h2>${home?(state.cat?categories.find(x=>x[0]===state.cat)[1]+' в Ставрополе':'Найдите своего мастера'):'Ваше избранное'}</h2><p id="resultCount"></p></div>${state.cat?'<button class="reset" data-reset>Все услуги </button>':''}</div><div class="toolbar"><select class="filter" id="price" aria-label="Цена"><option value="0">Цена: любая</option>${[1500,2500,3500,6000].map(p=>`<option value="${p}" ${+state.price===p?'selected':''}>До ${money(p)}</option>`).join('')}</select><select class="filter" id="area" aria-label="Район"><option value="">Район: любой</option>${['Центр','Юго-Западный','Северо-Западный'].map(a=>`<option ${state.area===a?'selected':''}>${a}</option>`).join('')}</select><select class="filter" id="sort" aria-label="Сортировка"><option value="recommended">Рекомендуемые</option><option value="cheap" ${state.sort==='cheap'?'selected':''}>Сначала дешевле</option><option value="rating" ${state.sort==='rating'?'selected':''}>По оценке</option></select><input class="search" id="search" placeholder="Поиск услуги или мастера" aria-label="Поиск услуги или мастера" value="${esc(state.search)}"></div><div class="grid" id="results"></div></section>${home?`<section class="how" aria-label="Как это работает"><div><b>01</b><section><h3>Выберите, что хочется</h3><p>Нужная услуга и подходящая цена.<br>Всё остальное можно уточнить позже.</p></section></div><div><b>02</b><section><h3>Найдите своё совпадение</h3><p>Посмотрите работы, познакомьтесь<br>с мастером, почитайте отзывы.</p></section></div><div><b>03</b><section><h3>Оставьте заявку</h3><p>Выберите желаемое время.<br>Мастер подтвердит вашу запись.</p></section></div></section>`:''}`;results();for(const key of ['price','area','sort'])$('#'+key).addEventListener('change',e=>{state[key]=e.target.value;results()});$('#search').addEventListener('input',e=>{state.search=e.target.value;results()})}
function profile(id){const m=masters.find(x=>x.id===id);if(!m){location.hash='';return}app.innerHTML=`<button class="back" data-view="home">&larr; Все мастера</button><div class="profile-layout"><div><img class="profile-image" src="assets/${m.image}.jpg" alt="${m.title}"><div class="demo-note">Иллюстративное фото · демонстрационный профиль</div></div><section class="profile-info"><div class="eyebrow">${m.role}</div><h1>${m.name}</h1><div class="rating"><span class="star">★</span><strong>${m.rating}</strong><span class="muted">· ${m.reviews} ${m.reviews===31?'отзыв':m.reviews===24?'отзыва':'отзывов'} · опыт ${m.experience}</span></div><p class="location">⌖ Ставрополь, ${m.address} · ${m.area}</p><p class="intro">${m.text}</p><span class="badge">✓ Пример статуса: документы проверены</span><div class="price"><span>${m.service}<br><small class="muted">${m.time} минут</small></span><strong>${money(m.price)}</strong></div><button class="primary" data-book="${m.id}">Записаться к мастеру </button> <button class="outline" data-save="${m.id}">${saved.includes(m.id)?'♥ Сохранён':'♡ Сохранить'}</button></section></div><div class="profile-sections"><h2>Работы</h2><article class="review"><strong>${m.title}</strong><p>${m.work}</p><small>Стоимость: ${money(m.price)} · длительность: ${m.time} минут<br>Учебный пример. Фотография не является подтверждённой работой указанного мастера.</small></article><h2>Услуги и цены</h2><div class="service-row"><div><p>${m.service}</p><small>${m.time} минут · ${money(m.price)}</small></div><button class="outline" data-book="${m.id}">Выбрать</button></div><h2>Отзывы</h2><div class="review"><strong>Демонстрационный отзыв · ★ 5,0</strong><p>Обсудили пожелания перед началом, объяснили этапы и уход. Результат понравился.</p><small>Пример оформления отзыва. Реального посещения не было.</small></div><details><summary>Образование и документы</summary><p>Здесь будет название документа, учебное заведение и дата проверки. В этом концепте реальные документы не загружены, квалификация не проверялась.</p><p>Проверка документа подтверждает сведения о документе и не гарантирует результат услуги.</p></details><details><summary>Где принимает мастер</summary><p>Демонстрационный адрес: Ставрополь, ${m.address}. Адрес приведён для примера и не является местом приёма указанного человека.</p></details></div><div class="mobile-cta"><button class="primary" data-book="${m.id}">Записаться · ${money(m.price)}</button></div>`}
function openBooking(id){const m=masters.find(x=>x.id===id),today=new Date();today.setDate(today.getDate()+1);today.setMinutes(today.getMinutes()-today.getTimezoneOffset());const min=today.toISOString().slice(0,10);$('#modalBody').innerHTML=`<div class="eyebrow">Заявка на запись</div><h2>Время для себя</h2><p>Укажите удобное время. В рабочем сервисе мастер подтвердит его или предложит другое.</p><div class="summary-box"><strong>${m.name}</strong><br>${m.service} · ${money(m.price)}<br><span class="muted">${m.time} минут · Ставрополь</span></div><form id="bookingForm"><div class="form-pair"><div><label for="date">Желаемая дата</label><input required type="date" id="date" name="date" min="${min}" value="${min}"></div><div><label for="time">Время</label><select id="time" name="time">${['09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00','19:00'].map(t=>`<option>${t}</option>`).join('')}</select></div></div><label for="name">Как к вам обращаться?</label><input name="name" id="name" autocomplete="given-name" required maxlength="60" placeholder="Ваше имя"><label for="phone">Телефон для подтверждения</label><input name="phone" id="phone" type="tel" autocomplete="tel" required minlength="10" maxlength="22" placeholder="+7 999 123-45-67"><p>Это демо: заявка останется только в вашем браузере. Не указывайте реальные личные данные.</p><button class="primary" type="submit">Отправить демозаявку </button></form>`;modal.showModal();$('#bookingForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const dt=new Date(f.get('date')+'T'+f.get('time'));if(dt<=new Date()){ $('#date').setCustomValidity('Выберите дату и время в будущем');$('#date').reportValidity();return}const phone=String(f.get('phone')).replace(/\D/g,'');if(phone.length<10||phone.length>15||!/^[+0-9\s()-]+$/.test(String(f.get('phone')))){$('#phone').setCustomValidity('Укажите телефон: от 10 до 15 цифр');$('#phone').reportValidity();return}const name=String(f.get('name')).trim();if(!name){$('#name').setCustomValidity('Введите имя');$('#name').reportValidity();return}bookings.unshift({id:Date.now(),master:id,date:f.get('date'),time:f.get('time'),name,status:'pending'});persist();$('#modalBody').innerHTML=`<div class="success-icon">✓</div><h2>Демозаявка сохранена</h2><p>${esc(name)}, вы прошли весь путь записи. В настоящем сервисе мастер получит заявку и подтвердит время.</p><div class="summary-box"><strong>${m.name}</strong><br>${m.service}<br>${new Date(f.get('date')+'T12:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}, ${f.get('time')} · ${money(m.price)}</div><p>Сейчас заявка хранится только в этом браузере. Мастеру ничего не отправлено.</p><button class="primary" id="goBookings">Посмотреть мои записи</button>`;$('#goBookings').onclick=()=>{modal.close();location.hash='bookings'}});for(const sel of ['#date','#time','#phone','#name'])$(sel).addEventListener('input',()=>{$('#date').setCustomValidity('');$('#phone').setCustomValidity('');$('#name').setCustomValidity('')})}
function myBookings(){app.innerHTML=`<button class="back" data-view="home">&larr; Найти мастера</button><div class="section-head"><div><h2>Мои записи</h2><p>Демонстрационные заявки в этом браузере</p></div></div>${bookings.length?bookings.map(b=>{const m=masters.find(x=>x.id===b.master);return m?`<article class="booking"><div><span class="status ${b.status==='cancelled'?'cancelled':''}">${b.status==='cancelled'?'Отменена':'Демо · ожидает подтверждения'}</span><h3 style="margin-top:15px">${m.service}</h3><p>${m.name}<br>${new Date(b.date+'T12:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}, ${b.time} · ${money(m.price)}</p></div>${b.status!=='cancelled'?`<button class="outline" data-cancel="${b.id}">Отменить заявку</button>`:''}</article>`:''}).join(''):`<div class="empty"><h2>Пока нет записей</h2><p>Найдите мастера и выберите удобное время.</p><button class="primary" data-view="home">Найти мастера</button></div>`}`}
function render(scroll=true){const route=location.hash.slice(1);if(route.startsWith('master/')){state.view='profile';profile(+route.split('/')[1])}else if(route==='bookings'){state.view='bookings';myBookings()}else{state.view=route==='saved'?'saved':'home';listing()}if(scroll)window.scrollTo({top:0,behavior:'instant'})}
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){if(v.dataset.view==='home'){state.cat='';state.price=0;state.area='';state.search=''}if(location.hash==='#'+(v.dataset.view==='home'?'':v.dataset.view))render();else location.hash=v.dataset.view==='home'?'':v.dataset.view}const c=e.target.closest('[data-cat]');if(c){state.cat=state.cat===c.dataset.cat?'':c.dataset.cat;render(false);$('#catalog').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}const s=e.target.closest('[data-save]');if(s)favorite(+s.dataset.save);const b=e.target.closest('[data-book]');if(b)openBooking(+b.dataset.book);if(e.target.closest('[data-reset]')){state.cat='';state.price=0;state.area='';state.search='';state.sort='recommended';if(state.view==='saved'&&!saved.length)location.hash='';else render(false)}const cancel=e.target.closest('[data-cancel]');if(cancel){const id=+cancel.dataset.cancel;$('#modalBody').innerHTML='<h2>Отменить заявку?</h2><p>Демозаявка останется в истории с отметкой «Отменена».</p><button class="primary" id="confirmCancel">Да, отменить</button> <button class="outline" id="keepBooking">Оставить заявку</button>';modal.showModal();$('#confirmCancel').onclick=()=>{bookings=bookings.map(b=>b.id===id?{...b,status:'cancelled'}:b);persist();modal.close();render(false);toast('Заявка отменена')};$('#keepBooking').onclick=()=>modal.close()}});
$('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});window.addEventListener('hashchange',()=>render());render();
